#!/usr/bin/env bash
set -euo pipefail
root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"; report="${SECURITY_REPORT_DIR:-$root/reports/security}"; mkdir -p "$report"; declare -A state
run(){ local name="$1";shift; if command -v "$1" >/dev/null 2>&1;then if "$@";then state[$name]=passed;else state[$name]=findings_or_failure;fi;else state[$name]=tool_missing;fi;}
cd "$root";run dependency_audit pip-audit -r backend/requirements.txt -f json -o "$report/pip-audit.json";run python_sast bandit -r backend -x backend/tests -f json -o "$report/bandit.json";run owasp_sast semgrep --config p/owasp-top-ten --json --output "$report/semgrep.json" backend
if command -v gitleaks >/dev/null 2>&1;then run secret_scan gitleaks detect --source . --report-format json --report-path "$report/gitleaks.json" --no-banner; evidence=gitleaks.json;else if python tools/secret_heuristic.py --root . --output "$report/secret-heuristic.json";then state[secret_scan]=passed_heuristic;else state[secret_scan]=findings_or_failure;fi;evidence='secret-heuristic.json (fallback)';fi
{ echo '# Allamni-Apex Security Report';echo;echo "Generated: $(date -u +%Y-%m-%dT%H:%M:%SZ)";echo;echo '| Control | Status | Evidence |';echo '|---|---|---|';echo "| Dependency audit | ${state[dependency_audit]} | pip-audit.json |";echo "| Python SAST | ${state[python_sast]} | bandit.json |";echo "| OWASP SAST | ${state[owasp_sast]} | semgrep.json |";echo "| Secret scan | ${state[secret_scan]} | ${evidence} |";echo;echo 'Review raw evidence and remediate open findings before production cutover.';} > "$report/summary.md";cat "$report/summary.md"
